package openingrouter

import (
	"context"
	"testing"
)

var helloWorldExampleAudio = ""

func TestCreateTranscription(t *testing.T) {
	client := tCreateClient(t)

	data := STTRequest{
		Model: "google/chirp-3",
		InputAudio: STTInputAudio{
			Data:   helloWorldExampleAudio,
			Format: "wav",
		},
	}

	resp, err := client.CreateTranscription(context.Background(), data)

	tAssertNil(t, err)

	tAssertNotNil(t, resp)

	tAssertContainsFold(t, resp.Text, "hello")
	tAssertContainsFold(t, resp.Text, "world")

	usage := resp.Usage

	tAssertNotNil(t, usage)
	tAssertNotNil(t, usage.Cost)

	testUsage += *usage.Cost
}
